const menu = [
  ['Overview','⌂'],['SalarySense','◈'],['CostCompass','◉'],['SpendWise AI','↗'],['SafetyNet','⬡'],['DebtShield','▣'],['WealthPath AI','⌁'],['SalaryDecode','▤'],['GoalPilot','◎'],['FinGuide AI','✦'],['FutureCast AI','◌'],['FinTwin Simulator','◇'],['ML Studio','⚒'],
];
const aux = [['Transactions','↕'],['Bills & reminders','◷'],['Bank connections','▤'],['Reports','▧'],['Settings','⚙']];
const savedProfile=JSON.parse(localStorage.getItem('fintwin-profile')||'{}');
const state={active:'Overview',light:localStorage.getItem('fintwin-light')==='true',profile:false,query:'',dataset:null,bills:[],bankConnections:[],bankConfigured:false,profile:{full_name:savedProfile.full_name||'Ahamed Shaik',email:savedProfile.email||'',city:savedProfile.city||'',monthly_salary:savedProfile.monthly_salary||0,essential_expenses:savedProfile.essential_expenses||0,employment_status:savedProfile.employment_status||'Employed',experience:savedProfile.experience||'1–2 years',currency:savedProfile.currency||'INR · Indian Rupee',photo:savedProfile.photo||''},summary:null,goals:JSON.parse(localStorage.getItem('fintwin-goals')||'[]'),authenticated:false,tx:JSON.parse(localStorage.getItem('fintwin-transactions')||'[]')};
const inr=n=>'₹'+Math.abs(n).toLocaleString('en-IN');
const html=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let apiToken=sessionStorage.getItem('fintwin-token')||'';
const API=(location.port==='5173'||location.port==='5174')?`http://${location.hostname}:8000/api/v1`:'/api/v1';
async function api(path,options={}){const headers=new Headers(options.headers||{});if(apiToken)headers.set('Authorization',`Bearer ${apiToken}`);const response=await fetch(`${API}${path}`,{...options,headers,credentials:'include'});let data={};try{data=await response.json()}catch{}if(!response.ok)throw Error(data.detail||`Request failed (${response.status})`);return data}
function localProfileSave(){localStorage.setItem('fintwin-profile',JSON.stringify(state.profile))}
function money(v){return Number(v||0)}
function txFromApi(t){const amount=money(t.amount)*(t.kind==='income'?1:-1);return {id:t.id,merchant:t.merchant,category:t.category,date:new Date(t.occurred_at).toLocaleDateString('en-IN',{day:'numeric',month:'short'}),amount,icon:(t.merchant||'?').slice(0,1).toUpperCase(),tone:t.kind==='income'?'green':'blue'} }
async function refreshAccount(){if(!apiToken&&location.port==='5173')return;try{const [profile,transactions,summary,goals]=await Promise.all([api('/profile'),api('/transactions?limit=100'),api('/dashboard/summary'),api('/goals')]);state.profile={...state.profile,...profile,monthly_salary:money(profile.monthly_salary),essential_expenses:money(profile.essential_expenses),employment_status:profile.employment_status||'Employed',experience:profile.experience||'1–2 years',currency:profile.currency||'INR · Indian Rupee'};state.tx=transactions.items.map(txFromApi);state.summary=summary;state.goals=goals.items;try{state.bills=(await api('/bills')).items}catch{}state.authenticated=true;localProfileSave();try{const photo=await fetch(`${API}/profile/photo`,{headers:apiToken?{Authorization:`Bearer ${apiToken}`}:{},credentials:'include'});if(photo.ok){if(state.profile.photo?.startsWith('blob:'))URL.revokeObjectURL(state.profile.photo);state.profile.photo=URL.createObjectURL(await photo.blob())}}catch{}render()}catch(error){if(/401|token|credential/i.test(error.message)){apiToken='';sessionStorage.removeItem('fintwin-token');state.authenticated=false;toast('Session expired. Please connect again.')}else console.warn('FinTwin account refresh:',error.message)}}
const root=document.getElementById('root');
function sidebar(){return `<aside class="sidebar"><div class="brand"><div class="brand-mark">✳</div><span>FinTwin<span class="brand-ai">.AI</span></span><button class="mobile-close icon-button" data-act="close">×</button></div><div class="workspace-switch"><div class="workspace-avatar">A</div><div class="workspace-copy"><strong>Personal workspace</strong><span>Free plan</span></div><span>⌄</span></div><div class="nav-label">WORKSPACE</div><nav class="nav-list">${menu.map(([n,i])=>`<button class="nav-item ${state.active===n?'active':''}" data-nav="${n}"><span class="nav-ico">${i}</span><span>${n}</span>${n==='FinGuide AI'?'<span class="nav-new">AI</span>':''}</button>`).join('')}</nav><div class="nav-divider"></div><div class="nav-label">MANAGE</div><nav class="nav-list bottom-nav">${aux.map(([n,i])=>`<button class="nav-item ${state.active===n?'active':''}" data-nav="${n}"><span class="nav-ico">${i}</span><span>${n}</span></button>`).join('')}</nav><div class="sidebar-bottom"><div class="upgrade-card"><div class="upgrade-icon">✧</div><strong>Unlock your full potential</strong><span>Get smarter insights with FinTwin Pro.</span><button data-toast="Pro plans are coming soon">Explore plans →</button></div><div class="sidebar-user" data-nav="Profile"><div class="user-avatar">${avatar()}</div><div class="user-copy"><strong>${html(state.profile.full_name)}</strong><span>${html(state.profile.email||'Not connected')}</span></div><span>···</span></div></div></aside>`;}
function header(){return `<header class="topbar"><div class="topbar-left"><button class="icon-button mobile-menu" data-act="menu">☰</button><div class="breadcrumb"><strong>${state.active==='Overview'?'AI Assistant':state.active}</strong></div></div><div class="topbar-actions"><label class="search-box"><span>⌕</span><input id="search" placeholder="Search transactions..." value="${html(state.query)}"><kbd>⌘ K</kbd></label><button class="icon-button notification-button" data-act="notifications">♧<i></i></button><button class="top-profile" data-act="profile"><div class="user-avatar small">${avatar()}</div><span>${html(state.profile.full_name)}</span><span>⌄</span></button></div></header>`;}
function footer(){return `<footer class="dashboard-footer"><span>FinTwin AI · Your money, in sync.</span><span>ⓘ Financial tools are informational and not a guarantee of outcomes.</span></footer>`;}
function pageHeading(title='Good morning, Ahamed',desc="Here's what's happening with your money this month.",actions=true){return `<div class="page-heading"><div><div class="eyebrow"><span class="live-dot"></span> ${title==='Good morning, Ahamed'?'YOUR FINANCIAL OVERVIEW':'FINANCIAL WORKSPACE'}</div><h1>${title} ${title==='Good morning, Ahamed'?'<span class="wave">✦</span>':''}</h1><p>${desc}</p></div>${actions?`<div class="heading-actions"><button class="button secondary" data-act="report">⇩ Export report</button><button class="button primary" data-act="add"><b>＋</b> Add transaction</button></div>`:''}</div>`;}
function spark(){return `<div class="sparkline">${[23,32,28,38,34,47,43,57,48,61,55,68].map(x=>`<i style="height:${x}%"></i>`).join('')}</div>`;}
function kpi(title,value,detail,icon,color){return `<div class="kpi-card kpi-${color}"><div class="kpi-top"><span>${title}</span><div class="kpi-icon">${icon}</div></div><div class="kpi-value">${value}</div><div class="kpi-bottom"><div class="kpi-detail"><span class="trend positive">↗ ${detail}</span> <span>vs last month</span></div>${spark()}</div><div class="kpi-glow"></div></div>`;}
function chartSvg(){const inc=[84,84,88,88,88,92,92,92,92,92],exp=[51,47,53,49,51,49,52,48,51,48];const w=720,h=205,px=33,py=17;const y=v=>py+(100-v)/100*(h-py-17),x=i=>px+i*(w-px-7)/(inc.length-1);const path=(arr)=>arr.map((v,i)=>`${i?'L':'M'}${x(i)},${y(v)}`).join(' ');const labels=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];return `<svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" class="line-chart"><defs><linearGradient id="bluefill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#5887fa" stop-opacity=".23"/><stop offset="1" stop-color="#5887fa" stop-opacity="0"/></linearGradient><linearGradient id="tealfill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#35d5bf" stop-opacity=".13"/><stop offset="1" stop-color="#35d5bf" stop-opacity="0"/></linearGradient></defs>${[0,25,50,75,100].map(v=>`<line x1="${px}" y1="${y(v)}" x2="${w}" y2="${y(v)}" stroke="var(--grid)" stroke-dasharray="3 5"/><text x="0" y="${y(v)+3}" fill="var(--muted)" font-size="9">${v===0?'0':v+'k'}</text>`).join('')}<path d="${path(inc)} L${x(inc.length-1)},${h} L${px},${h} Z" fill="url(#bluefill)"/><path d="${path(exp)} L${x(exp.length-1)},${h} L${px},${h} Z" fill="url(#tealfill)"/><path d="${path(inc)}" fill="none" stroke="#5887fa" stroke-width="2.5" vector-effect="non-scaling-stroke"/><path d="${path(exp)}" fill="none" stroke="#35d5bf" stroke-width="2.5" vector-effect="non-scaling-stroke"/>${labels.map((t,i)=>`<text x="${px+i*(w-px-7)/11}" y="${h-1}" fill="var(--muted)" font-size="9" text-anchor="middle">${t}</text>`).join('')}</svg>`;}
function donut(){const colors=['#6794ff','#38d9c3','#a78bfa','#f8b65e','#485a77'];let sum=48350,at=0;const seg=[18200,12450,6800,6250,4650].map((v,i)=>{let start=at;at+=v/sum*360;return `${colors[i]} ${start}deg ${at-3}deg`}).join(',');return `<div class="donut-css" style="background:conic-gradient(from 90deg,${seg})"><div class="donut-center"><span>Total spent</span><strong>₹48,350</strong><small>this month</small></div></div>`;}
function txRows(){return state.tx.filter(t=>(t.merchant+' '+t.category).toLowerCase().includes(state.query.toLowerCase())).slice(0,5).map(t=>`<div class="tx-row"><div class="tx-merchant"><div class="merchant-icon ${t.tone}">${t.icon}</div><strong>${html(t.merchant)}</strong></div><span class="tx-category">${html(t.category)}</span><span class="tx-date">${html(t.date)}</span><strong class="tx-amount ${t.amount>0?'income-amount':''}">${t.amount>0?'+':'−'}${inr(t.amount)}</strong><button class="icon-button tx-more" data-toast="${html(t.merchant)} · ${html(t.category)}">···</button></div>`).join('');}
function dashboard(){return `${pageHeading()}<div class="demo-strip"><span class="demo-dot"></span><span><strong>Preview data</strong> · Replace with your real finances anytime.</span><button data-act="import">⇧ Import data</button></div><section class="kpi-grid">${kpi('Monthly income','₹92,000','4.5%','▣','blue')}${kpi('Monthly expenses','₹48,350','2.8%','▤','teal')}${kpi('Total savings','₹2,84,500','12.8%','♧','violet')}${kpi('Savings rate','47.4%','3.2%','◉','amber')}</section><section class="middle-grid"><div class="panel cash-panel"><div class="panel-head"><div><h2>Cash flow</h2><p>Income vs expenses over time</p></div><div class="period-control"><button class="period-active">12 months</button><button data-toast="Showing 6 month view">6 months</button><button data-toast="Showing 30 day view">30 days</button></div></div><div class="chart-legend"><span><i class="legend-blue"></i> Income</span><span><i class="legend-teal"></i> Expenses</span><span class="chart-total">Net savings <strong>₹43,650</strong><b class="trend positive">+8.2%</b></span></div><div class="cash-chart">${chartSvg()}</div></div><div class="panel spending-panel"><div class="panel-head"><div><h2>Spending breakdown</h2><p>Where your money goes</p></div><button class="icon-button" data-nav="SpendWise AI">···</button></div>${donut()}<div class="spend-list">${[['Housing',18200,'#6794ff'],['Food & dining',12450,'#38d9c3'],['Transport',6800,'#a78bfa'],['Lifestyle',6250,'#f8b65e'],['Other',4650,'#485a77']].map(([n,v,c])=>`<div class="spend-item"><i style="background:${c}"></i><span>${n}</span><strong>${inr(v)}</strong><em>${Math.round(v/48350*100)}%</em></div>`).join('')}</div></div></section><section class="lower-grid"><div class="panel transactions-panel"><div class="panel-head"><div><h2>Recent transactions</h2><p>Your latest activity across accounts</p></div><button class="text-button" data-nav="Transactions">View all →</button></div><div class="transactions-table"><div class="tx-head"><span>TRANSACTION</span><span>CATEGORY</span><span>DATE</span><span>AMOUNT</span><span></span></div>${txRows()}</div></div><div class="panel goals-panel"><div class="panel-head"><div><h2>Savings goals</h2><p>Small steps, big milestones</p></div><button class="icon-button" data-act="goal">＋</button></div><div class="goal-feature"><div class="goal-icon">♧</div><div class="goal-copy"><strong>Emergency fund</strong><span>Target · ₹4,00,000</span></div><span class="goal-percent">68%</span></div><div class="goal-progress"><span style="width:68%"></span></div><div class="goal-stats"><strong>₹2,72,000 <span>saved</span></strong><span>₹1,28,000 to go</span></div><div class="goal-footer"><div class="goal-mini-icon">▦</div><span>You're on track to reach your goal<br><strong>by June 2027</strong></span><button data-nav="GoalPilot">›</button></div></div></section><section class="insight-banner"><div class="insight-orb">✧</div><div class="insight-copy"><div class="insight-label">YOUR FINANCIAL COPILOT <span>✦ AI INSIGHT</span></div><h3>You're building great momentum, Ahamed.</h3><p>You've saved <strong>₹43,650</strong> this month. Putting an extra ₹5,000 toward your emergency fund could get you to your target <strong>1 month sooner.</strong></p></div><button class="button insight-button" data-nav="FinGuide AI">Explore insight →</button><div class="banner-glow"></div></section>${footer()}`;}
function avatar(){return `<img src="${html(state.profile.photo||'/public/assets/profile-photo.jpeg')}" alt="Profile photo"/>`;}
function robot(){return `<div class="robot-stage"><div class="robot-beam"></div><svg class="robot-svg" viewBox="0 0 150 190" role="img" aria-label="FinTwin AI assistant"><defs><linearGradient id="bot" x1="0" x2="1" y1="0" y2="1"><stop stop-color="#fff"/><stop offset=".55" stop-color="#d8c7ff"/><stop offset="1" stop-color="#9d6aff"/></linearGradient><linearGradient id="visor" x1="0" x2="1"><stop stop-color="#110c27"/><stop offset="1" stop-color="#311664"/></linearGradient><filter id="glow"><feGaussianBlur stdDeviation="5" result="b"/><feMerge><feMergeNode in="b"/><feMergeNode in="SourceGraphic"/></feMerge></filter></defs><path d="M75 12v15" stroke="#d3afff" stroke-width="4"/><circle cx="75" cy="10" r="5" fill="#e6c5ff" filter="url(#glow)"/><rect x="39" y="26" width="72" height="59" rx="22" fill="url(#bot)" stroke="#eedfff" stroke-width="2"/><rect x="46" y="37" width="58" height="36" rx="15" fill="url(#visor)"/><ellipse cx="61" cy="55" rx="6" ry="8" fill="#c78cff" filter="url(#glow)"/><ellipse cx="89" cy="55" rx="6" ry="8" fill="#c78cff" filter="url(#glow)"/><path d="M59 81v8m32-8v8" stroke="#a576ea" stroke-width="5" stroke-linecap="round"/><rect x="49" y="89" width="52" height="48" rx="17" fill="url(#bot)" stroke="#e5d5ff" stroke-width="2"/><path d="M63 101h24" stroke="#7454ac" stroke-width="5" stroke-linecap="round"/><circle cx="75" cy="119" r="5" fill="#bc81ff"/><path d="M49 99 31 115m70-16 18 16M61 135l-5 25m33-25 5 25" fill="none" stroke="url(#bot)" stroke-width="12" stroke-linecap="round"/><path d="M46 163h18m22 0h18" stroke="#d8c7ff" stroke-width="9" stroke-linecap="round"/><circle cx="29" cy="117" r="5" fill="#c78cff"/><circle cx="121" cy="117" r="5" fill="#c78cff"/></svg></div>`;}
function dashboardReference(){
  const profile=state.profile, summary=state.summary||{};
  const hasLiveData=state.authenticated||state.tx.length>0||money(profile.monthly_salary)>0||money(profile.essential_expenses)>0;
  const recordedIncome=state.tx.filter(t=>t.amount>0).reduce((n,t)=>n+t.amount,0);
  const income=state.authenticated?(money(summary.income)||money(profile.monthly_salary)):money(profile.monthly_salary)||recordedIncome||92000;
  const localExpenses=state.tx.filter(t=>t.amount<0).reduce((n,t)=>n+Math.abs(t.amount),0);
  const expenses=state.authenticated?(money(summary.expenses)||money(profile.essential_expenses)):(localExpenses||money(profile.essential_expenses)||48350);
  const net=income-expenses, rate=income?Math.max(0,net/income*100):0;const monthEnd=new Date();monthEnd.setDate(monthEnd.getDate()+30);const pendingBills=state.bills.filter(b=>b.active&&new Date(b.due_date+'T00:00:00')<=monthEnd).reduce((n,b)=>n+money(b.amount),0);
  const categories=hasLiveData?Object.entries(state.tx.filter(t=>t.amount<0).reduce((a,t)=>(a[t.category]=(a[t.category]||0)+Math.abs(t.amount),a),{})).sort((a,b)=>b[1]-a[1]).slice(0,5):[['Housing',18200],['Food & dining',12450],['Transport',6800],['Lifestyle',6250],['Other',4650]];
  const totalSpend=categories.reduce((n,x)=>n+x[1],0)||expenses;
  const currentGoals=state.goals.length?state.goals:state.authenticated?[]:[{name:'Emergency fund',target_amount:400000,current_amount:272000},{name:'Travel fund',target_amount:120000,current_amount:50400}];
  const pct=g=>Math.min(100,Math.round(money(g.current_amount)/Math.max(1,money(g.target_amount))*100));
  const greeting=profile.full_name||'Your FinTwin';
  const profileContext=[profile.employment_status,profile.experience,profile.city].filter(Boolean).join(' · ');
  const dataTag=hasLiveData?'YOUR SAVED PROFILE':'PREVIEW DATA';
  const transactions=state.tx.length?state.tx.slice(0,3):(!state.authenticated?[{merchant:'Sample grocery',category:'Groceries',date:'Preview',amount:-840,icon:'S',tone:'purple'}]:[]);
  return `${pageHeading(`Good morning, ${html(greeting)}`,profileContext?`Your financial overview · ${html(profileContext)}.`:'Your personal financial twin is ready. What would you like to know?',false)}<div class="demo-strip"><span class="demo-dot"></span><span><strong>${dataTag}</strong> · ${hasLiveData?'Figures use your saved profile, transactions and goals.':'Connect your account or save a profile to personalise this overview.'}</span><button data-nav="ML Studio">⇧ Import dataset</button></div>
  <section class="assistant-dashboard"><div class="panel assistant-panel"><div class="assistant-welcome"><div><span class="assistant-status"><i></i> FIN GUIDE · ACTIVE</span><h2>Hey ${html(greeting.split(' ')[0])}!</h2><p>How can I help you with your finances today?</p></div>${robot()}</div><div class="assistant-chips">${[['⌕','Spending','What did I spend this month?'],['▧','Suggest budget','Suggest a budget for me'],['▣','Upcoming bills','What bills are coming up?'],['▤','Current saving balance','How much have I saved?'],['⇄','Transfer','Plan a savings transfer']].map(([ic,n,q])=>`<button class="assistant-chip" data-assist="${q}"><span>${ic}</span>${n}</button>`).join('')}</div>
  <div class="assistant-answer"><div class="assistant-answer-heading"><div class="guide-spark small">✧</div><span>FIN GUIDE <i>${dataTag}</i></span></div><p>${state.authenticated?`Your saved transactions show ${inr(expenses)} in expenses and ${inr(income)} in income. Your net cash flow is ${inr(net)}. Add transactions to keep this snapshot current.`:`Your preview estimates ${inr(expenses)} in monthly spending against ${inr(income)} in income. Connect your private account and add your actual transactions to replace these estimates.`}</p><div class="assistant-actions"><button class="button secondary" data-nav="SpendWise AI">Review spending <span>→</span></button><button class="button secondary" data-nav="Profile">Update profile</button></div></div>
  <div class="assistant-spend-card"><div class="spend-card-title"><div><strong>Your spending breakdown</strong><span>${hasLiveData?'From your saved information':'Illustrative preview'}</span></div><button class="text-button" data-nav="SpendWise AI">Full analysis →</button></div><div class="spend-visual"><div class="spend-chart-ring"><span>${inr(totalSpend)}<small>TOTAL SPENT</small></span></div><div class="spend-visual-list">${categories.map(([n,v],i)=>`<div><i style="background:${['#7d68f6','#37d7bf','#b25df2','#f05998','#f0bf49'][i]}"></i><span>${html(n)}</span><strong>${inr(v)}</strong></div>`).join('')||'<p>Add expense records to see category totals.</p>'}</div></div></div>
  <form class="assistant-input" id="assistant-form"><input id="assistant-question" placeholder="Ask me about your finances..."/><button type="button" class="voice-button" data-toast="Use the text field to ask FinGuide">♩</button><button class="send-button">➤</button></form></div>
  <div class="assistant-right"><div class="panel health-card"><div class="panel-head"><div><h2>Financial health score</h2><p>Based on your current cash flow</p></div><span class="health-info">ⓘ</span></div><div class="health-main"><div class="score-ring"><div><strong>${Math.round(Math.min(100,Math.max(0,rate*1.6)))}</strong><span>/100</span></div></div><div class="health-copy"><strong>${income&&net>=0?'You are spending within your income.':'Add income and expenses to see your cash flow.'}</strong><p>${income?`Your current savings rate is ${rate.toFixed(1)}%.`:'Enter your take-home pay in Profile.'}</p><button class="button secondary" data-nav="SafetyNet">Improve my score <span>→</span></button></div></div><div class="health-bottom"><span>${state.authenticated?'From your records':'Profile estimate'}</span><span>${Math.round(Math.min(100,Math.max(0,rate*1.6)))}/100</span></div></div>
  <div class="panel quick-overview"><div class="panel-head"><div><h2>Quick overview</h2><p>${state.authenticated?'Your saved account snapshot':'Your profile snapshot'}</p></div><button class="date-pill" data-nav="Profile">✎ &nbsp; Edit profile</button></div><div class="overview-track"><i></i><i></i><i></i></div><div class="overview-stats"><div><span>Available balance</span><strong>${inr(net)}</strong></div><div><span>Monthly income</span><strong>${inr(income)}</strong></div><div><span>Upcoming bills</span><strong>${inr(pendingBills)}</strong></div></div></div>
  <div class="panel goals-ring-card"><div class="panel-head"><div><h2>Savings goals</h2><p>${currentGoals.length?`${currentGoals.length} active goal${currentGoals.length===1?'':'s'}`:'Create a goal to get started'}</p></div><button class="icon-button" data-act="goal">＋</button></div><div class="goals-rings"><div class="rings-graphic"><div class="ring outer"></div><div class="ring inner"></div><div class="rings-center"><strong>${currentGoals.length}</strong><span>ACTIVE<br>GOALS</span></div></div><div class="ring-legend">${currentGoals.slice(0,2).map((g,i)=>`<div><i style="background:${i?'#e84994':'#2acfe0'}"></i><span>${html(g.name)}<strong>${pct(g)}%</strong></span></div>`).join('')||'<button class="text-button" data-act="goal">＋ Create your first goal</button>'}</div></div></div>
  <div class="panel recent-card"><div class="panel-head"><div><h2>Recent transactions</h2><p>Your latest financial activity</p></div><button class="text-button" data-nav="Transactions">View all →</button></div><div class="recent-list">${transactions.map(t=>`<div class="recent-row"><span class="merchant-icon ${t.tone}">${html(t.icon)}</span><span><strong>${html(t.merchant)}</strong><small>${html(t.category)} · ${html(t.date)}</small></span><b class="${t.amount>0?'income-amount':''}">${t.amount>0?'+':'−'}${inr(t.amount)}</b></div>`).join('')||'<p class="empty-state">Your transactions will appear here.</p>'}</div></div></div></section><div class="reference-disclaimer">ⓘ Financial figures use your own records after sign-in. Estimates are educational and may not include all bills or accounts.</div>${footer()}`;
}
function goalsPage(){return `${pageHeading('GoalPilot','Track savings targets and record contributions.',false)}<div class="panel goals-panel"><div class="panel-head"><div><h2>Your savings goals</h2><p>${state.goals.length} goal(s) · ${state.authenticated?'Synced to your account':'Saved on this device'}</p></div><button class="button primary" data-act="goal">＋ Create goal</button></div>${state.goals.map(g=>{const pct=Math.min(100,Math.round(money(g.current_amount)/Math.max(1,money(g.target_amount))*100));return `<div class="goal-feature"><div class="goal-icon">◎</div><div class="goal-copy"><strong>${html(g.name)}</strong><span>${inr(g.current_amount)} saved of ${inr(g.target_amount)}</span></div><span class="goal-percent">${pct}%</span><button class="text-button" data-goal-contribute="${html(g.id)}">＋ Add savings</button><button class="icon-button" data-goal-delete="${html(g.id)}" aria-label="Delete ${html(g.name)}">⌫</button></div><div class="goal-progress"><span style="width:${pct}%"></span></div><div class="goal-stats"><strong>${inr(g.target_amount-money(g.current_amount))} <span>remaining</span></strong><span>${g.target_date?`Target ${html(new Date(g.target_date).toLocaleDateString())}`:'No target date'}</span></div>`}).join('')||'<div class="empty-state">No goals yet. Create a savings goal to get started.</div>'}</div>${footer()}`}
function transactionsPage(){const rows=state.tx.filter(t=>(`${t.merchant} ${t.category}`).toLowerCase().includes(state.query.toLowerCase()));return `${pageHeading('Transactions','Search and manage the transactions saved to your workspace.')}<div class="panel transactions-panel"><div class="panel-head"><div><h2>All transactions</h2><p>${rows.length} record${rows.length===1?'':'s'} · ${state.authenticated?'Synced to your private account':'Saved on this device'}</p></div><button class="button primary" data-act="add">＋ Add transaction</button></div><div class="transactions-table"><div class="tx-head"><span>TRANSACTION</span><span>CATEGORY</span><span>DATE</span><span>AMOUNT</span><span></span></div>${rows.map(t=>`<div class="tx-row"><div class="tx-merchant"><div class="merchant-icon ${t.tone}">${html(t.icon)}</div><strong>${html(t.merchant)}</strong></div><span class="tx-category">${html(t.category)}</span><span class="tx-date">${html(t.date)}</span><strong class="tx-amount ${t.amount>0?'income-amount':''}">${t.amount>0?'+':'−'}${inr(t.amount)}</strong><button class="icon-button" data-delete-tx="${html(t.id||'')}">⌫</button></div>`).join('')||'<div class="empty-state">No transactions yet. Add your first income or expense.</div>'}</div></div>${footer()}`}
function reportsPage(){const income=state.authenticated?money(state.summary?.income):money(state.profile.monthly_salary),expenses=state.authenticated?money(state.summary?.expenses):state.tx.filter(t=>t.amount<0).reduce((n,t)=>n+Math.abs(t.amount),0),net=income-expenses;return `${pageHeading('Reports','A downloadable snapshot of your profile and saved financial activity.',false)}<div class="panel module-summary"><span class="summary-caption">Net cash flow</span><strong class="summary-amount">${inr(net)}</strong><span class="summary-helper">${state.tx.length} saved transaction(s) · ${state.goals.length} savings goal(s)</span><button class="button primary" data-act="prepare">⇩ Download report</button></div>${footer()}`}
function settingsPage(){return `${pageHeading('Settings','Personalise readability and manage this device.',false)}<div class="panel profile-details"><div class="panel-head"><div><h2>Display</h2><p>Choose the appearance that is easier for you to read.</p></div></div><div class="settings-row"><span class="settings-icon">◐</span><div><strong>Light appearance</strong><span>Switch between the dark and light dashboard.</span></div><button class="button secondary" data-act="theme">${state.light?'Switch to dark':'Switch to light'}</button></div><div class="settings-row"><span class="settings-icon blue">Aa</span><div><strong>Large readable text</strong><span>Text is enlarged across the app for easier reading.</span></div><span class="profile-lock">On</span></div><div class="settings-row"><span class="settings-icon">↻</span><div><strong>Refresh account data</strong><span>Reload profile, transactions, and goals from the API.</span></div><button class="button secondary" data-act="refresh">Refresh now</button></div></div>${footer()}`}
function billsPage(){return `${pageHeading('Bills & reminders','Create due-date reminders and recurring bill entries.',false)}<div class="panel ml-upload"><div class="panel-head"><div><h2>Add a bill reminder</h2><p>FinTwin checks due dates daily and shows reminders in the notification center.</p></div></div><form id="bill-form" class="profile-form-grid"><label>Bill name<input name="name" required maxlength="120" placeholder="Electricity bill"></label><label>Amount (INR)<input name="amount" type="number" min="0.01" step="0.01" required></label><label>Category<select name="category"><option>Bills & utilities</option><option>Housing</option><option>Subscriptions</option><option>Insurance</option><option>Other</option></select></label><label>Due date<input name="due_date" type="date" required></label><label>Repeat<select name="recurrence"><option value="monthly">Monthly</option><option value="weekly">Weekly</option><option value="yearly">Yearly</option><option value="once">One time</option></select></label><label>Remind me (days before)<input name="reminder_days" type="number" min="0" max="30" value="3"></label><button class="button primary">Save reminder</button></form></div><div class="panel ml-upload" style="margin-top:14px"><div class="panel-head"><div><h2>Upcoming and saved bills</h2><p>Marking paid records an expense and advances recurring bills.</p></div><button class="button secondary" data-act="reload-bills">Refresh</button></div><div id="bill-list" class="transaction-list">Loading bills…</div></div>${footer()}`;}
function bankPage(){return `${pageHeading('Bank connections','Link accounts through user-approved Account Aggregator consent.',false)}<div class="panel ml-upload"><div class="panel-head"><div><h2>Connect a bank account</h2><p>Bank login credentials are entered only on the regulated provider’s consent page. FinTwin never asks for bank passwords or PINs.</p></div></div><div id="bank-config" class="profile-note">Checking provider configuration…</div><form id="bank-form" class="profile-form-grid"><label>AA handle (VUA)<input name="vua" type="text" required placeholder="mobile@your-aa"></label><label>Transactions from<input name="from_date" type="date" required></label><label>Through<input name="to_date" type="date" required></label><button class="button primary">Request consent link</button></form></div><div class="panel ml-upload" style="margin-top:14px"><div class="panel-head"><div><h2>Connected consents</h2><p>Refresh consent after approval, then sync transactions.</p></div></div><div id="bank-list" class="transaction-list">Loading connections…</div></div>${footer()}`;}
function modulePage(){const income=state.authenticated?(money(state.summary?.income)||money(state.profile.monthly_salary)):money(state.profile.monthly_salary);const expenses=state.authenticated?(money(state.summary?.expenses)||money(state.profile.essential_expenses)):state.tx.filter(t=>t.amount<0).reduce((n,t)=>n+Math.abs(t.amount),0)||money(state.profile.essential_expenses);const net=income-expenses;const liveValue=state.active==='SafetyNet'?state.goals.reduce((n,g)=>n+money(g.current_amount),0):state.active==='CostCompass'?money(state.profile.essential_expenses)||expenses:state.active==='SpendWise AI'?expenses:state.active==='DebtShield'?state.tx.filter(t=>/debt|loan|credit/i.test(t.category+' '+t.merchant)).reduce((n,t)=>n+Math.abs(t.amount),0):state.active==='FutureCast AI'?net:net;const fallbackValue=state.active==='SafetyNet'?272000:state.active==='DebtShield'?184500:43650;const displayValue=state.authenticated||state.tx.length||money(state.profile.monthly_salary)||money(state.profile.essential_expenses)?liveValue:fallbackValue;if(state.active==='GoalPilot')return goalsPage();if(state.active==='Transactions')return transactionsPage();if(state.active==='Reports')return reportsPage();if(state.active==='Settings')return settingsPage();if(state.active==='Profile')return profilePage();if(state.active==='FinGuide AI')return guidePage();if(state.active==='FinTwin Simulator')return simulatorPage();if(state.active==='WealthPath AI')return wealthPage();if(state.active==='SalaryDecode')return salaryPage();if(state.active==='ML Studio')return mlStudioPage();if(state.active==='Bills & reminders')return billsPage();if(state.active==='Bank connections')return bankPage();let icon=(menu.find(x=>x[0]===state.active)||aux.find(x=>x[0]===state.active)||['','⚙'])[1];return `${pageHeading(state.active,desc[state.active]||'Your financial activity, organised in one place.',false)}<div class="module-content-grid"><div class="module-primary"><div class="panel module-summary"><div class="module-summary-top"><div class="summary-icon">${icon}</div><span class="preview-data-tag">${state.authenticated?'YOUR SAVED DATA':'PROFILE / PREVIEW'}</span></div><span class="summary-caption">${state.active==='SafetyNet'?'Emergency fund balance':state.active==='DebtShield'?'Total outstanding debt':state.active==='FutureCast AI'?'Projected month-end balance':state.active==='CostCompass'?'Essential monthly expenses':state.active==='SpendWise AI'?'Total tracked spending':'Available this month'}</span><strong class="summary-amount">${inr(displayValue)}</strong><span class="summary-helper"><span class="trend positive">↗ 8.2%</span> compared with last month</span></div><div class="panel module-chart"><div class="panel-head"><div><h2>${state.active==='FutureCast AI'?'Cash flow outlook':state.active==='SafetyNet'?'Emergency fund progress':'Monthly trends'}</h2><p>${state.authenticated?'Calculated from your saved account records':'Calculated from your saved profile and transactions'}</p></div><button class="button secondary" data-act="month">October 2026⌄</button></div><div class="cash-chart">${chartSvg()}</div></div><div class="panel module-transactions"><div class="panel-head"><div><h2>Recent activity</h2><p>Latest records in your workspace</p></div><button class="text-button" data-act="add">＋ Add record</button></div><div class="transactions-table">${txRows()}</div></div></div><div class="module-aside"><div class="panel module-quick-actions"><div class="panel-head"><div><h2>Quick actions</h2><p>Keep things up to date</p></div></div><button class="quick-action" data-act="add"><span class="quick-action-icon blue">＋</span><span><strong>Add transaction</strong><small>Log income or an expense</small></span>›</button><button class="quick-action" data-act="goal"><span class="quick-action-icon teal">◎</span><span><strong>Create a goal</strong><small>Plan your next milestone</small></span>›</button><button class="quick-action" data-act="import"><span class="quick-action-icon violet">⇧</span><span><strong>Import your data</strong><small>CSV and Excel support</small></span>›</button></div><div class="panel recommendation-card"><div class="recommendation-icon">✧</div><div class="eyebrow">A SMALL NEXT STEP</div><h3>Give your savings a direction.</h3><p>Set a monthly contribution goal and see what feels achievable with your current cash flow.</p><button class="text-button" data-nav="GoalPilot">Explore goal planning →</button></div><div class="panel module-note">ⓘ ${state.authenticated?'This summary is calculated from your saved records.':'Add your own financial records to replace these preview estimates.'} Calculations are educational estimates.</div></div></div>${footer()}`;}
function guideAnswer(question){const q=question.toLowerCase(), income=state.authenticated?(money(state.summary?.income)||money(state.profile.monthly_salary)):money(state.profile.monthly_salary), expenses=state.authenticated?money(state.summary?.expenses):state.tx.filter(t=>t.amount<0).reduce((n,t)=>n+Math.abs(t.amount),0)||money(state.profile.essential_expenses), net=income-expenses;const category=Object.entries(state.tx.filter(t=>t.amount<0).reduce((a,t)=>(a[t.category]=(a[t.category]||0)+Math.abs(t.amount),a),{})).sort((a,b)=>b[1]-a[1])[0];const prefix=state.authenticated?'From your saved account records: ':'From the information currently available: ';if(q.includes('goal'))return prefix+(state.goals.length?`you have ${state.goals.length} goal(s). ${state.goals.slice(0,2).map(g=>`${g.name} is ${Math.min(100,Math.round(money(g.current_amount)/Math.max(1,money(g.target_amount))*100))}% complete`).join('; ')}.`:'you have no saved savings goals yet. Create a goal to track progress.');if(q.includes('spend')||q.includes('expense')||q.includes('save less'))return prefix+(expenses?`your recorded expenses total ${inr(expenses)}. ${category?`${category[0]} is your largest recorded category at ${inr(category[1])}. `:''}${state.authenticated?'':'This may not include every expense.'}`:'no expenses are recorded yet. Add transactions to build your spending view.');if(q.includes('afford')||q.includes('purchase')){const amount=Number(q.match(/[\d,]+/)?.[0]?.replaceAll(',','')||0);return prefix+(amount?`your current recorded net cash flow is ${inr(net)}. A purchase of ${inr(amount)} would leave ${inr(net-amount)} before other bills. Review upcoming obligations before deciding.`:`your recorded net cash flow is ${inr(net)}. Include upcoming bills before making a large purchase.`)}if(q.includes('saving')||q.includes('balance')||q.includes('income'))return prefix+`monthly income is ${inr(income)}, expenses are ${inr(expenses)}, and net cash flow is ${inr(net)}. ${income?`That is a ${Math.max(0,net/income*100).toFixed(1)}% savings rate.`:'Add take-home pay in your profile for a savings rate.'}`;if(q.includes('bill'))return prefix+`there are ${state.tx.filter(t=>/bill|rent|utility/i.test(t.category+' '+t.merchant)).length} bill-related transaction(s) saved. This app does not yet have due-date reminders; enter bill dates in your calendar.`;return prefix+`income is ${inr(income)} and recorded expenses are ${inr(expenses)}, leaving ${inr(net)} net cash flow. Ask about spending, your savings rate, or a goal. ${state.authenticated?'':'Figures may be incomplete until you connect an account and add records.'}`}
function guidePage(){const income=state.authenticated?(money(state.summary?.income)||money(state.profile.monthly_salary)):money(state.profile.monthly_salary);const expenses=state.authenticated?money(state.summary?.expenses):state.tx.filter(t=>t.amount<0).reduce((n,t)=>n+Math.abs(t.amount),0)||money(state.profile.essential_expenses);const savings=income?Math.max(0,(income-expenses)/income*100):0;return `${pageHeading('FinGuide AI',desc['FinGuide AI'],false)}<div class="guide-layout"><div class="panel guide-panel"><div class="guide-hero"><div class="guide-spark">✧</div><div><span>YOUR FINANCIAL COPILOT</span><h2>Money questions, meet real answers.</h2><p>Ask about your finances. Every number is calculated from your records and clearly explained.</p></div></div><div class="chat-window" id="chat-window"><div class="chat-empty"><div class="chat-empty-icon">◉</div><strong>What would you like to understand?</strong><p>Try a question below, or ask anything about your finances.</p></div></div><div class="suggested-questions">${['Why am I saving less this month?','Can I afford a ₹20,000 purchase?','How do I reach my goal sooner?'].map(q=>`<button data-question="${q}">${q} →</button>`).join('')}</div><form class="chat-input" id="chat-form"><input id="chat-question" placeholder="Ask FinGuide about your finances..."><button class="button primary">➜</button></form><span class="chat-disclaimer">FinGuide uses your authorised financial records. Guidance is informational, not financial advice.</span></div><aside class="guide-aside"><div class="panel context-card"><div class="panel-head"><div><h2>Your financial snapshot</h2><p>Context used for answers</p></div></div><div class="context-row"><span>Monthly income</span><strong>${inr(income)}</strong></div><div class="context-row"><span>Monthly expenses</span><strong>${inr(expenses)}</strong></div><div class="context-row"><span>Savings rate</span><strong class="teal-text">${savings.toFixed(1)}%</strong></div><div class="context-row"><span>Active goals</span><strong>${state.goals.length} goals</strong></div><span class="preview-data-tag">${state.authenticated?'Saved account':'Profile estimate'}</span></div><div class="panel copilot-note"><span>✧</span><strong>How FinGuide works</strong><p>Answers use transparent calculations on the financial information in your account. No transaction details are invented.</p></div></aside></div>${footer()}`;}
function simulatorPage(){return `${pageHeading('FinTwin Simulator',desc['FinTwin Simulator'],false)}<div class="simulator-layout"><div class="panel simulator-controls"><div class="sim-section-head"><div class="sim-icon">◇</div><div><h2>Shape your scenario</h2><p>Adjust the sliders to see a possible future.</p></div></div>${[['Monthly savings','monthly',25000,5000,60000,1000,'₹'],['Annual return assumption','rate',10,1,15,1,'%'],['Time horizon','years',10,1,30,1,' yrs']].map(([label,key,val,min,max,step,unit])=>`<div class="sim-input-group"><div class="sim-input-heading"><label>${label}</label><strong id="${key}-label">${key==='monthly'?'₹':''}${val.toLocaleString('en-IN')}${key==='rate'?'%':key==='years'?' years':''}</strong></div><input type="range" min="${min}" max="${max}" step="${step}" value="${val}" id="${key}"/><div class="range-labels"><span>${key==='monthly'?'₹':''}${Number(min).toLocaleString('en-IN')}${unit}</span><span>${key==='monthly'?'₹':''}${Number(max).toLocaleString('en-IN')}${unit}</span></div></div>`).join('')}<div class="sim-note">ⓘ Illustrative projection using monthly contributions and monthly compounding. Actual returns vary and are not guaranteed.</div><button class="button secondary full-button" data-act="reset-sim">Reset assumptions</button></div><div class="simulator-results"><div class="scenario-label"><span class="scenario-dot"></span> HYPOTHETICAL SCENARIO <span class="scenario-separator">vs</span><span class="scenario-dot blue-dot"></span> CURRENT PATH</div><div class="sim-total"><div><span>Projected value at year <b id="sim-years">10</b></span><strong id="sim-total">₹51<small> L</small></strong><p>With <span id="sim-monthly">₹25,000</span> monthly contributions</p></div><div class="sim-growth-badge">↗ <span id="sim-growth">₹30,00,000</span> estimated growth</div></div><div class="panel sim-chart-panel"><div class="panel-head"><div><h2>Scenario growth over time</h2><p>Illustrative compounded contributions</p></div></div><div class="scenario-chart"><div class="cash-chart">${chartSvg()}</div></div><div class="chart-legend sim-legend"><span><i class="legend-blue"></i> Scenario</span><span><i class="legend-teal"></i> Current path</span></div></div><div class="scenario-footnote">⬡ Your baseline uses preview figures and is for exploration only.</div></div></div>${footer()}`;}
function wealthPage(){return `${pageHeading('WealthPath AI',desc['WealthPath AI'],false)}<div class="calculator-layout"><div class="panel calculator-controls"><div class="sim-section-head"><div class="sim-icon">⌁</div><div><h2>SIP growth calculator</h2><p>Explore the power of regular contributions.</p></div></div><div class="calc-field"><label>Monthly investment <strong id="wealth-month-label">₹10,000</strong></label><input type="range" min="500" max="100000" step="500" value="10000" id="wealth-month"></div><div class="calc-field"><label>Expected annual return <strong id="wealth-rate-label">10%</strong></label><input type="range" min="1" max="20" value="10" id="wealth-rate"></div><div class="calc-field"><label>Investment period <strong id="wealth-years-label">10 yrs</strong></label><input type="range" min="1" max="40" value="10" id="wealth-years"></div><div class="sim-note">ⓘ Returns are hypothetical and not guaranteed. Investments carry risk.</div></div><div class="panel wealth-result"><div class="eyebrow">ILLUSTRATIVE OUTCOME</div><h2 id="wealth-total">₹20.7 <small>L</small></h2><p>Estimated future value after <span id="wealth-years-copy">10</span> years</p><div class="wealth-breakdown"><div><span>Invested amount</span><strong id="wealth-invested">₹12.0L</strong></div><div><span>Potential growth</span><strong class="teal-text" id="wealth-growth">₹8.7L</strong></div></div><div class="wealth-disclaimer">Educational calculator · No guaranteed returns</div></div></div>${footer()}`;}
function salaryPage(){return `${pageHeading('SalaryDecode',desc['SalaryDecode'],false)}<div class="salary-decode-layout"><div class="panel salary-input-card"><div class="sim-section-head"><div class="sim-icon">▤</div><div><h2>Compensation snapshot</h2><p>Enter your CTC for a simple breakdown estimate.</p></div></div><label class="calc-field">Annual CTC<input class="full-input" id="ctc" type="number" value="1104000"></label><div class="sim-note">ⓘ Illustrative estimate only; actual take-home depends on employer structure, declarations, applicable tax rules, and your payslip.</div></div><div class="panel salary-result"><div class="eyebrow">ESTIMATED MONTHLY TAKE-HOME</div><h2 id="takehome">₹77,280</h2><p>Illustrative amount after estimated deductions</p><div class="salary-bar"><span></span></div><div class="salary-lines"><div><span>Estimated gross monthly</span><strong id="gross-monthly">₹92,000</strong></div><div><span>Estimated deductions</span><strong id="deductions">₹14,720</strong></div><div><span>Estimated take-home</span><strong class="teal-text" id="net-monthly">₹77,280</strong></div></div></div></div>${footer()}`;}
function mlStudioPage(){return `${pageHeading('ML Studio',desc['ML Studio'],false)}<div class="panel ml-intro"><div class="recommendation-icon">⚒</div><div><h2>Train on your own financial data.</h2><p>Upload a dataset to validate its structure, inspect data quality, and evaluate a model against a simple baseline. No model is activated automatically.</p></div><span class="preview-data-tag">DATASET-DRIVEN · NO DEMO MODEL</span></div><div class="ml-grid"><div class="panel ml-upload"><div class="panel-head"><div><h2>1. Connect your account</h2><p>Authenticate with your local FinTwin API.</p></div></div><form id="api-login" class="modal-form"><label class="account-name-field" style="display:none">Full name<input name="full_name" placeholder="Your name"></label><label>Email<input name="email" type="email" placeholder="you@example.com" required></label><label>Password<input name="password" type="password" required autocomplete="current-password"></label><button class="button primary full-button">Connect securely</button><small class="chat-disclaimer">Credentials are sent only to the configured local API and are kept in memory for this page.</small></form><button type="button" id="create-account" class="text-button account-mode">New here? Create an account</button><div class="profile-note">Your API must be running at <code>http://localhost:8000</code>.</div></div><div class="panel ml-upload"><div class="panel-head"><div><h2>2. Import a dataset</h2><p>CSV or Excel · max 20 MB · private to your account</p></div></div><label class="dataset-drop">⇧<strong>Choose a financial dataset</strong><span>CSV, XLSX, or XLS · PII should not be used as features</span><input id="dataset-file" type="file" accept=".csv,.xlsx,.xls"></label><button class="text-button sample-data-button" data-act="sample-dataset">Use the supplied synthetic FinTwin sample ↗</button><div id="dataset-result" class="dataset-result">No dataset selected yet.</div></div><div class="panel ml-train"><div class="panel-head"><div><h2>3. Configure an evaluation</h2><p>Choose a labelled target and useful predictors.</p></div></div><form id="train-form" class="modal-form"><label>Target column<select id="target-column" required disabled><option value="">Import a dataset first</option></select></label><label>Feature columns<input id="feature-columns" placeholder="Pick a dataset first" disabled></label><label>Task<select id="task-kind"><option value="regression">Regression · numeric target</option><option value="classification">Classification · category target</option></select></label><button id="train-button" class="button primary full-button" disabled>Train and evaluate</button></form><div id="train-result" class="dataset-result">Evaluation metrics appear here after training. New models require explicit approval.</div></div><div class="panel ml-notes"><div class="panel-head"><div><h2>Model safeguards</h2><p>What this workflow checks</p></div></div><div class="settings-row"><span class="settings-icon">✓</span><div><strong>Leakage resistant split</strong><span>Fixed-seed train/validation/test split; preprocessing fits on train only.</span></div></div><div class="settings-row"><span class="settings-icon blue">✓</span><div><strong>Baseline comparison</strong><span>Dummy baseline plus a random forest candidate.</span></div></div><div class="settings-row"><span class="settings-icon">✓</span><div><strong>Approval required</strong><span>Evaluated models stay inactive until you approve one.</span></div></div></div></div>${footer()}`;}
function profilePage(){const p=state.profile;return `${pageHeading('Your profile','Update your profile. Saved details personalise the dashboard overview.',false)}<div class="profile-layout"><div class="panel profile-card"><div class="profile-cover"><div class="cover-stars">✦　✦　✦</div></div><div class="profile-avatar-wrap"><div class="profile-avatar" id="profile-avatar">${avatar()}</div><label class="photo-edit">＋<input id="photo" type="file" accept="image/jpeg,image/png,image/webp"></label></div><div class="profile-identity"><h2 id="profile-display-name">${html(p.full_name)}</h2><p id="profile-display-email">${html(p.email||'Connect an account to add email')}</p><span class="profile-status"><i></i> Personal profile</span></div><div class="profile-card-divider"></div><div class="profile-stat"><div><span>City</span><strong id="profile-display-city">${html(p.city||'Add your city')}</strong></div><div><span>Monthly income</span><strong id="profile-display-salary">${inr(p.monthly_salary)}</strong></div></div></div><div class="panel profile-details"><div class="panel-head"><div><h2>Personal information</h2><p>Details shown in your dashboard and financial tools.</p></div><span class="profile-lock">⬡ Private</span></div><div class="profile-form-grid"><label>Full name<input id="profile-name" value="${html(p.full_name)}" autocomplete="name"></label><label>Email address<input id="profile-email" type="email" value="${html(p.email)}" ${state.authenticated?'disabled':''}></label><label>Employment status<select id="profile-employment">${['Employed','Self-employed','Student','Other'].map(x=>`<option ${x===p.employment_status?'selected':''}>${x}</option>`).join('')}</select></label><label>Work experience<select id="profile-experience">${['Less than 1 year','1–2 years','3–5 years','5+ years'].map(x=>`<option ${x===p.experience?'selected':''}>${x}</option>`).join('')}</select></label><label>City of residence<input id="profile-city" value="${html(p.city)}" autocomplete="address-level2"></label><label>Monthly take-home salary<input id="profile-salary" type="number" min="0" step="100" value="${money(p.monthly_salary)}" inputmode="decimal"></label><label>Preferred currency<select id="profile-currency"><option>INR · Indian Rupee</option></select></label><label>Monthly essential expenses<input id="profile-essentials" type="number" min="0" step="100" value="${money(p.essential_expenses)}" inputmode="decimal"></label></div><div class="profile-note">⬡ Your saved name, city, salary and essential expenses appear in your Overview.</div><button class="button primary" style="margin-top:12px" data-act="saveprofile">Save changes</button></div><div class="panel profile-security"><div class="settings-row"><div class="settings-icon">⬡</div><div><strong>Account security</strong><span>Secure sign-in and private financial records.</span></div><button class="text-button" data-nav="ML Studio">Manage account ›</button></div><div class="settings-row"><div class="settings-icon blue">♧</div><div><strong>Notifications</strong><span>Reminders appear from your saved financial records.</span></div><button class="text-button" data-nav="Settings">Configure ›</button></div></div></div>${footer()}`;}
function trainingFeatures(columns,target){const pii=['user','id','name','full','email','phone','address','account','pan','aadhaar'];const future=['had_layoff_in_year','min_savings_12m','savings_12m_actual','risk_flag_12m'];return columns.map(c=>c.name).filter(name=>name!==target&&!['age','city'].includes(name.toLowerCase())&&!name.toLowerCase().split('_').some(x=>pii.includes(x))&&!future.includes(name.toLowerCase())).join(', ');}
async function loadBills(){const box=document.getElementById('bill-list');if(!box)return;if(!apiToken&&!state.authenticated){box.innerHTML='Sign in through ML Studio to save and view your reminders.';return}try{const data=await api('/bills');state.bills=data.items;box.innerHTML=data.items.length?data.items.map(b=>`<div class="transaction-row"><div class="transaction-icon blue">◷</div><div class="transaction-info"><strong>${html(b.name)}</strong><span>${html(b.category)} · due ${html(b.due_date)} · ${html(b.recurrence)}</span></div><strong>${inr(money(b.amount))}</strong>${b.active?`<button class="button secondary" data-bill-paid="${b.id}">Mark paid</button>`:'<span class="profile-note">Paid once</span>'}<button class="icon-button" aria-label="Delete bill" data-bill-delete="${b.id}">×</button></div>`).join(''):'No reminders saved yet.';document.querySelectorAll('[data-bill-paid]').forEach(b=>b.onclick=async()=>{try{await api(`/bills/${b.dataset.billPaid}/paid`,{method:'POST'});await refreshAccount();await loadBills();toast('Payment recorded')}catch(err){toast(err.message)}});document.querySelectorAll('[data-bill-delete]').forEach(b=>b.onclick=async()=>{try{await api(`/bills/${b.dataset.billDelete}`,{method:'DELETE'});await loadBills()}catch(err){toast(err.message)}})}catch(err){box.textContent=err.message}}
async function loadBankConnections(){const box=document.getElementById('bank-list'),config=document.getElementById('bank-config');if(!box)return;if(!apiToken&&!state.authenticated){box.textContent='Sign in through ML Studio to manage bank connections.';return}try{const data=await api('/bank-connections');state.bankConnections=data.items;state.bankConfigured=data.configured;if(config)config.textContent=data.configured?'Setu AA is configured. New bank links require your explicit consent.':'Setu AA credentials are not configured on this API. Add FIU credentials in backend/.env to enable consent requests.';box.innerHTML=data.items.length?data.items.map(c=>`<div class="transaction-row"><div class="transaction-icon blue">▤</div><div class="transaction-info"><strong>${html(c.provider)} · ${html(c.consent_status)}</strong><span>${c.accounts.map(a=>html(a.masked_account_number)).join(', ')||'No account details returned'}${c.last_synced_at?' · synced '+html(new Date(c.last_synced_at).toLocaleString()):''}</span></div><a class="button primary" href="${html(c.consent_url)}" target="_blank" rel="noopener noreferrer">Continue consent</a><button class="button secondary" data-bank-refresh="${c.id}">Refresh</button><button class="button secondary" data-bank-sync="${c.id}" ${c.consent_status!=='ACTIVE'?'disabled':''}>Sync transactions</button><button class="icon-button" data-bank-revoke="${c.id}">×</button></div>`).join(''):'No bank consents linked.';document.querySelectorAll('[data-bank-refresh]').forEach(b=>b.onclick=async()=>{try{await api(`/bank-connections/${b.dataset.bankRefresh}/refresh`,{method:'POST'});await loadBankConnections()}catch(err){toast(err.message)}});document.querySelectorAll('[data-bank-sync]').forEach(b=>b.onclick=async()=>{try{const r=await api(`/bank-connections/${b.dataset.bankSync}/sync`,{method:'POST'});await refreshAccount();await loadBankConnections();toast(`${r.imported} transactions imported`)}catch(err){toast(err.message)}});document.querySelectorAll('[data-bank-revoke]').forEach(b=>b.onclick=async()=>{try{await api(`/bank-connections/${b.dataset.bankRevoke}`,{method:'DELETE'});await loadBankConnections()}catch(err){toast(err.message)}})}catch(err){box.textContent=err.message}}
async function openNotifications(){if(!apiToken&&!state.authenticated){toast('Sign in to view bill reminders');return}try{const data=await api('/notifications');document.querySelector('.modal-backdrop')?.remove();const rows=data.items.map(n=>`<div class="notification-row"><div class="notif-icon amber">◷</div><div><strong>${html(n.title)}</strong><p>${html(n.message)}</p>${n.read?'':'<button class="text-button" data-notification-read="'+n.id+'">Mark read</button>'}</div></div>`).join('');document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop"><div class="modal"><div class="modal-head"><div><div class="eyebrow">REMINDERS</div><h2>Notifications</h2></div><button class="icon-button" data-act="closemodal">×</button></div>${rows||'<p class="profile-note">No upcoming bill reminders.</p>'}</div></div>`);document.querySelectorAll('[data-notification-read]').forEach(b=>b.onclick=async()=>{try{await api(`/notifications/${b.dataset.notificationRead}/read`,{method:'PATCH'});await openNotifications()}catch(err){toast(err.message)}})}catch(err){toast(err.message)}}
function render(){document.body.classList.toggle('is-mobile-menu',false);root.innerHTML=`<div class="app-shell ${state.light?'light':'dark'}">${sidebar()}<main class="main-area">${header()}<div class="page-content">${state.active==='Overview'?dashboardReference():modulePage()}</div></main></div>`;bind();bindModules();bindRobot();}
function toast(s){let old=document.querySelector('.toast');old?.remove();const d=document.createElement('div');d.className='toast';d.innerHTML=`<span>✓</span>${html(s)}`;document.body.append(d);setTimeout(()=>d.remove(),2600);}
function modal(kind){
 const heading=kind==='goal'?'Create savings goal':kind==='report'?'Export your report':'Add transaction';
 const form=kind==='report'?`<div class="report-modal"><div class="report-preview">▧<strong>Financial overview</strong><span>Prepared from your current records</span></div><p>The report includes your profile, saved transactions, spending totals and goals.</p><button class="button primary full-button" data-act="prepare">⇩ Download report</button></div>`:kind==='goal'?`<form class="modal-form" id="goal-form"><label>Goal name<input name="name" placeholder="e.g. Emergency fund" required></label><label>Target amount (₹)<input name="target_amount" type="number" min="1" value="25000" required></label><label>Already saved (₹)<input name="current_amount" type="number" min="0" value="0"></label><label>Target date<input name="target_date" type="date"></label><button class="button primary full-button">◎ Save goal</button></form>`:`<form class="modal-form" id="tx-form"><div class="toggle-row"><button type="button" class="selected" data-kind="expense">Expense</button><button type="button" data-kind="income">Income</button></div><label>Merchant or description<input name="merchant" placeholder="e.g. Grocery shopping" required></label><label>Amount (₹)<input name="amount" type="number" min="0.01" step="0.01" placeholder="0.00" required></label><label>Category<select name="category"><option>Food & dining</option><option>Housing</option><option>Transport</option><option>Lifestyle</option><option>Utilities</option><option>Health</option><option>Income</option><option>Other</option></select></label><button class="button primary full-button">＋ Save transaction</button></form>`;
 document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop"><div class="modal"><div class="modal-head"><div><div class="eyebrow">FINANCIAL WORKSPACE</div><h2>${heading}</h2></div><button class="icon-button" data-act="closemodal">×</button></div>${form}</div></div>`);
 document.querySelectorAll('[data-kind]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-kind]').forEach(x=>x.classList.remove('selected'));b.classList.add('selected')});
 document.querySelector('#tx-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget,kind=f.querySelector('[data-kind].selected')?.dataset.kind||'expense';const payload={merchant:f.merchant.value.trim(),category:f.category.value,kind,amount:Number(f.amount.value)};try{if(apiToken||state.authenticated){await api('/transactions',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});await refreshAccount()}else{const t={...payload,date:'Just now',amount:payload.amount*(kind==='income'?1:-1),icon:payload.merchant[0].toUpperCase(),tone:kind==='income'?'green':'blue'};t.id=crypto.randomUUID();state.tx.unshift(t);localStorage.setItem('fintwin-transactions',JSON.stringify(state.tx))}document.querySelector('.modal-backdrop')?.remove();render();toast(`${kind==='income'?'Income':'Expense'} saved`)}catch(err){toast(err.message)}});
 document.querySelector('#goal-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget;const goal={name:f.name.value.trim(),target_amount:Number(f.target_amount.value),current_amount:Number(f.current_amount.value||0),target_date:f.target_date.value?`${f.target_date.value}T00:00:00Z`:null};try{if(apiToken||state.authenticated){await api('/goals',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(goal)});await refreshAccount()}else{state.goals.push({...goal,id:crypto.randomUUID()});localStorage.setItem('fintwin-goals',JSON.stringify(state.goals))}document.querySelector('.modal-backdrop')?.remove();render();toast('Savings goal saved')}catch(err){toast(err.message)}});
}
function bind(){
 document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{state.active=b.dataset.nav;render();window.scrollTo({top:0,behavior:'instant'});document.querySelector('.main-area')?.scrollTo({top:0,behavior:'instant'})});
 document.querySelectorAll('[data-goal-contribute]').forEach(b=>b.onclick=async()=>{const goal=state.goals.find(g=>g.id===b.dataset.goalContribute);if(!goal)return;const amount=Number(prompt(`How much did you add to ${goal.name}?`));if(!Number.isFinite(amount)||amount<=0)return;try{const updated={...goal,current_amount:money(goal.current_amount)+amount};if(apiToken||state.authenticated)await api(`/goals/${encodeURIComponent(goal.id)}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({current_amount:updated.current_amount})});Object.assign(goal,updated);localStorage.setItem('fintwin-goals',JSON.stringify(state.goals));if(apiToken||state.authenticated)await refreshAccount();else render();toast('Savings progress updated')}catch(err){toast(err.message)}});
 document.querySelectorAll('[data-goal-delete]').forEach(b=>b.onclick=async()=>{const id=b.dataset.goalDelete;if(!confirm('Delete this savings goal?'))return;try{if(apiToken||state.authenticated)await api(`/goals/${encodeURIComponent(id)}`,{method:'DELETE'});state.goals=state.goals.filter(g=>g.id!==id);localStorage.setItem('fintwin-goals',JSON.stringify(state.goals));if(apiToken||state.authenticated)await refreshAccount();else render();toast('Goal deleted')}catch(err){toast(err.message)}});
 document.querySelectorAll('[data-delete-tx]').forEach(b=>b.onclick=async()=>{const id=b.dataset.deleteTx;if(!confirm('Delete this transaction?'))return;try{if(apiToken&&id)await api(`/transactions/${encodeURIComponent(id)}`,{method:'DELETE'});state.tx=state.tx.filter(t=>t.id!==id);localStorage.setItem('fintwin-transactions',JSON.stringify(state.tx));if(apiToken||state.authenticated)await refreshAccount();else render();toast('Transaction deleted')}catch(err){toast(err.message)}});
 document.querySelectorAll('[data-act]').forEach(b=>b.onclick=async()=>{const a=b.dataset.act;if(a==='theme'){state.light=!state.light;localStorage.setItem('fintwin-light',String(state.light));render()}if(a==='refresh'){if(apiToken||state.authenticated)await refreshAccount();else{render();toast('Connect an account in ML Studio to sync data')}}if(a==='add')modal('transaction');if(a==='goal')modal('goal');if(a==='report')modal('report');if(a==='closemodal'||a==='close')document.querySelector('.modal-backdrop')?.remove();if(a==='menu')document.querySelector('.sidebar')?.classList.add('sidebar-open');if(a==='notifications')openNotifications();if(a==='profile'){state.active='Profile';render()}if(a==='import'){state.active='ML Studio';render()}if(a==='prepare'){const text=[`FinTwin AI financial overview`,`Name: ${state.profile.full_name}`,`City: ${state.profile.city||'Not set'}`,`Monthly take-home pay: ${inr(state.profile.monthly_salary)}`,`Essential expenses: ${inr(state.profile.essential_expenses)}`,``,`Transactions:`,...state.tx.map(t=>`${t.date} | ${t.merchant} | ${t.category} | ${t.amount>0?'+':'-'}${inr(t.amount)}`),``,`Savings goals:`,...state.goals.map(g=>`${g.name} | ${inr(g.current_amount)} / ${inr(g.target_amount)}`)].join('\n');const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([text],{type:'text/plain'}));link.download='fintwin-financial-overview.txt';link.click();URL.revokeObjectURL(link.href);document.querySelector('.modal-backdrop')?.remove();toast('Your financial overview downloaded')}if(a==='month')toast('Overview uses your saved transactions and profile');if(a==='saveprofile')await saveProfile()});
 document.querySelectorAll('[data-toast]').forEach(b=>b.onclick=()=>toast(b.dataset.toast));
 const search=document.getElementById('search');search?.addEventListener('input',e=>{state.query=e.target.value;const y=window.scrollY;render();const input=document.getElementById('search');input?.focus();input?.setSelectionRange(state.query.length,state.query.length);window.scrollTo(0,y)});
 document.getElementById('photo')?.addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;if(!file.type.startsWith('image/')||file.size>4e6){toast('Choose a JPEG, PNG or WebP image under 4 MB');return}try{if(apiToken||state.authenticated){const body=new FormData();body.append('file',file);await api('/profile/photo',{method:'POST',body});const photo=await fetch(`${API}/profile/photo`,{headers:apiToken?{Authorization:`Bearer ${apiToken}`}:{},credentials:'include'});if(!photo.ok)throw Error('Photo could not be loaded');state.profile.photo=URL.createObjectURL(await photo.blob())}else{const bitmap=await createImageBitmap(file),canvas=document.createElement('canvas'),scale=Math.min(1,512/Math.max(bitmap.width,bitmap.height));canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);state.profile.photo=canvas.toDataURL('image/jpeg',.78);bitmap.close()}document.getElementById('profile-avatar').innerHTML=`<img src="${state.profile.photo}" alt="Profile photo">`;localProfileSave();render();toast('Profile photo updated')}catch(err){toast(err.message)}});
 document.querySelector('.modal-backdrop')?.addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))e.target.remove()});
}
async function saveProfile(){const read=id=>document.getElementById(id)?.value?.trim()||'';const p={...state.profile,full_name:read('profile-name'),city:read('profile-city'),monthly_salary:Number(read('profile-salary')||0),essential_expenses:Number(read('profile-essentials')||0),employment_status:read('profile-employment'),experience:read('profile-experience'),currency:read('profile-currency')};if(!p.full_name){toast('Please enter your name');return}try{if(apiToken||state.authenticated){const result=await api('/profile',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({full_name:p.full_name,city:p.city,monthly_salary:p.monthly_salary,essential_expenses:p.essential_expenses,employment_status:p.employment_status,experience:p.experience,currency:'INR'})});state.profile={...p,...result,essential_expenses:money(result.essential_expenses),employment_status:result.employment_status,experience:result.experience,currency:p.currency};}else state.profile=p;localProfileSave();render();toast('Profile saved and dashboard updated')}catch(err){toast(`Profile was not saved: ${err.message}`)}}
function bindModules(){
  if(state.active==='Bills & reminders') loadBills();
  if(state.active==='Bank connections') loadBankConnections();  document.querySelectorAll('[data-assist]').forEach(b=>b.onclick=()=>{const q=b.dataset.assist;const input=document.getElementById('assistant-question');if(input){input.value=q;input.focus();input.dispatchEvent(new Event('change',{bubbles:true}))}});
  document.getElementById('assistant-form')?.addEventListener('submit',e=>{e.preventDefault();const input=document.getElementById('assistant-question'),q=input.value.trim();if(!q)return;const text=guideAnswer(q);document.querySelector('.assistant-answer p').textContent=text;const btn=document.createElement('button');btn.className='assistant-question-bubble';btn.textContent=q;document.querySelector('.assistant-answer').insertAdjacentElement('beforebegin',btn);input.value=''});
  document.querySelector('[data-act="sample-dataset"]')?.addEventListener('click',async()=>{if(!apiToken&&!state.authenticated){toast('Connect your account before uploading a dataset');return}try{const response=await fetch('/public/datasets/users.csv');if(!response.ok)throw Error('Could not load the supplied sample');const file=new File([await response.blob()],'fintwin_synthetic_users.csv',{type:'text/csv'});const transfer=new DataTransfer();transfer.items.add(file);const input=document.getElementById('dataset-file');input.files=transfer.files;input.dispatchEvent(new Event('change',{bubbles:true}));toast('Loading the supplied synthetic users dataset')}catch(err){toast(err.message||'Could not load the sample')}});
  let registerMode=false;document.getElementById('create-account')?.addEventListener('click',e=>{registerMode=!registerMode;document.querySelector('.account-name-field').style.display=registerMode?'flex':'none';e.currentTarget.textContent=registerMode?'Already have an account? Sign in':'New here? Create an account';document.querySelector('#api-login button[type=submit]').textContent=registerMode?'Create account':'Connect securely'});document.getElementById('api-login')?.addEventListener('submit',async e=>{e.preventDefault();const form=new FormData(e.currentTarget);try{let r;if(registerMode){r=await fetch(`${API}/auth/register`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:form.get('email'),password:form.get('password'),full_name:form.get('full_name')}),credentials:'include'})}else{r=await fetch(`${API}/auth/token`,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({username:form.get('email'),password:form.get('password')}),credentials:'include'})}const data=await r.json();if(!r.ok)throw Error(data.detail||'Could not connect');apiToken=location.port==='5173'?data.access_token:'';if(apiToken)sessionStorage.setItem('fintwin-token',apiToken);state.authenticated=true;await refreshAccount();toast(registerMode?'Your private FinTwin account is ready':'Connected to your private FinTwin account')}catch(err){toast(err.message||'API unavailable — start the backend first')}});
  document.getElementById('dataset-file')?.addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;if(!apiToken&&!state.authenticated){toast('Connect your account before uploading a dataset');return}if(file.size>20e6){toast('Dataset must be 20 MB or smaller');return}const result=document.getElementById('dataset-result');result.textContent='Uploading and validating your dataset…';const body=new FormData();body.append('file',file);try{const r=await fetch(`${API}/datasets`,{method:'POST',headers:apiToken?{Authorization:`Bearer ${apiToken}`}:{},credentials:'include',body});const data=await r.json();if(!r.ok)throw Error(data.detail||'Dataset validation failed');state.dataset=data;result.innerHTML=`<strong>${html(data.filename)}</strong><span>${data.validation.rows.toLocaleString()} rows · ${data.validation.columns} columns · ${data.validation.duplicate_rows} duplicate rows</span><small>SHA-256 ${data.checksum.slice(0,20)}…</small>`;const select=document.getElementById('target-column');select.innerHTML='<option value="">Choose target…</option>'+data.columns.map(c=>`<option value="${c.name}">${html(c.name)} · ${html(c.dtype)}</option>`).join('');select.disabled=false;document.getElementById('feature-columns').disabled=false;const preferred=data.columns.some(c=>c.name==='risk_flag_12m')?'risk_flag_12m':(data.columns.some(c=>c.name==='recommended_action')?'recommended_action':'');if(preferred){select.value=preferred;document.getElementById('task-kind').value='classification'}document.getElementById('feature-columns').value=trainingFeatures(data.columns,select.value);document.getElementById('train-button').disabled=false}catch(err){result.textContent=err.message||'Could not reach the local API';toast('Dataset upload failed')}});
  document.getElementById('target-column')?.addEventListener('change',e=>{if(!state.dataset)return;document.getElementById('feature-columns').value=trainingFeatures(state.dataset.columns,e.target.value)});
  document.getElementById('train-form')?.addEventListener('submit',async e=>{e.preventDefault();if(!state.dataset||(!apiToken&&!state.authenticated))return;const target=document.getElementById('target-column').value;const features=document.getElementById('feature-columns').value.split(',').map(x=>x.trim()).filter(Boolean);const form=new FormData();form.append('dataset_id',state.dataset.id);form.append('target',target);form.append('feature_columns',JSON.stringify(features));form.append('task',document.getElementById('task-kind').value);const result=document.getElementById('train-result');result.textContent='Training and evaluating against a baseline…';try{const r=await fetch(`${API}/training-runs`,{method:'POST',headers:apiToken?{Authorization:`Bearer ${apiToken}`}:{},credentials:'include',body:form});let data=await r.json();if(!r.ok)throw Error(data.detail||'Training failed');if(data.status==='queued'){result.textContent='Large dataset queued. Training is running in the background…';for(let attempt=0;attempt<600;attempt++){await new Promise(resolve=>setTimeout(resolve,2000));data=await api(`/training-runs/${data.id}`);if(data.status==='completed_pending_approval'||data.status==='failed')break}if(data.status==='failed')throw Error(data.metrics?.error||'Background training failed');if(data.status!=='completed_pending_approval')throw Error('Training is still running; return to ML Studio and check again')}result.innerHTML=`<strong>Evaluation complete · ${data.task}</strong><span>Model evaluation completed · approval required</span><pre>${html(JSON.stringify(data.metrics,null,2))}</pre><button class="button primary" id="activate-model">Approve and activate model v${data.version}</button>`;document.getElementById('activate-model').onclick=async()=>{try{const a=await fetch(`${API}/models/${data.model_id}/activate`,{method:'POST',headers:apiToken?{Authorization:`Bearer ${apiToken}`}:{},credentials:'include'});const out=await a.json();if(!a.ok)throw Error(out.detail);toast(`Model v${out.version} approved and activated`);document.getElementById('activate-model').textContent='Active model ✓';document.getElementById('activate-model').disabled=true}catch(err){toast(err.message)}}}catch(err){result.textContent=err.message||'Training failed'}});
  document.getElementById('bill-form')?.addEventListener('submit',async e=>{e.preventDefault();if(!apiToken&&!state.authenticated){toast('Connect your account in ML Studio to save bill reminders');return}const f=e.currentTarget,body={name:f.elements.namedItem('name').value.trim(),amount:Number(f.elements.namedItem('amount').value),category:f.elements.namedItem('category').value,due_date:f.elements.namedItem('due_date').value,recurrence:f.elements.namedItem('recurrence').value,reminder_days:Number(f.elements.namedItem('reminder_days').value)};try{await api('/bills',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});f.reset();await loadBills();toast('Bill reminder saved')}catch(err){toast(err.message)}});
  document.querySelectorAll('[data-bill-paid]').forEach(b=>b.onclick=async()=>{try{await api(`/bills/${b.dataset.billPaid}/paid`,{method:'POST'});await refreshAccount();await loadBills();toast('Payment recorded; recurring due date advanced')}catch(err){toast(err.message)}});
  document.querySelectorAll('[data-bill-delete]').forEach(b=>b.onclick=async()=>{try{await api(`/bills/${b.dataset.billDelete}`,{method:'DELETE'});await loadBills();toast('Bill reminder removed')}catch(err){toast(err.message)}});
  document.querySelector('[data-act="reload-bills"]')?.addEventListener('click',loadBills);
  document.getElementById('bank-form')?.addEventListener('submit',async e=>{e.preventDefault();if(!apiToken&&!state.authenticated){toast('Connect your account in ML Studio to connect a bank');return}const f=e.currentTarget,body={vua:f.elements.namedItem('vua').value,from_date:f.elements.namedItem('from_date').value,to_date:f.elements.namedItem('to_date').value};try{const c=await api('/bank-connections/consents',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});await loadBankConnections();toast('Consent requested. Use Continue consent to approve with your bank.')}catch(err){toast(err.message)}});
  document.querySelectorAll('[data-bank-refresh]').forEach(b=>b.onclick=async()=>{try{await api(`/bank-connections/${b.dataset.bankRefresh}/refresh`,{method:'POST'});await loadBankConnections();toast('Consent status refreshed')}catch(err){toast(err.message)}});
  document.querySelectorAll('[data-bank-sync]').forEach(b=>b.onclick=async()=>{try{const r=await api(`/bank-connections/${b.dataset.bankSync}/sync`,{method:'POST'});await refreshAccount();await loadBankConnections();toast(`${r.imported} new transaction(s) imported`)}catch(err){toast(err.message)}});
  document.querySelectorAll('[data-bank-revoke]').forEach(b=>b.onclick=async()=>{if(!confirm('Revoke this bank data consent and disconnect?'))return;try{await api(`/bank-connections/${b.dataset.bankRevoke}`,{method:'DELETE'});await loadBankConnections();toast('Bank consent revoked')}catch(err){toast(err.message)}});
  document.querySelectorAll('[data-question]').forEach(b=>b.onclick=()=>{document.getElementById('chat-question').value=b.dataset.question;});
  document.getElementById('chat-form')?.addEventListener('submit',e=>{e.preventDefault();const input=document.getElementById('chat-question'),q=input.value.trim();if(!q)return;const box=document.getElementById('chat-window');box.innerHTML=`<div class="chat-pair"><div class="chat-question">${q.replace(/[<>]/g,'')}</div><div class="chat-answer"><div class="guide-spark small">✧</div><span>${html(guideAnswer(q))}</span></div></div>`;input.value='';});
  const simKeys=['monthly','rate','years'];
  const updateSim=()=>{const m=Number(document.getElementById('monthly')?.value||25000),r=Number(document.getElementById('rate')?.value||10),y=Number(document.getElementById('years')?.value||10);const mr=r/1200,n=y*12,fv=mr?m*((Math.pow(1+mr,n)-1)/mr):m*n;const fmt=n=>'₹'+Math.round(n).toLocaleString('en-IN');const ml=(fv/100000).toFixed(1);document.getElementById('monthly-label')&&(document.getElementById('monthly-label').textContent=fmt(m));document.getElementById('rate-label')&&(document.getElementById('rate-label').textContent=r+'%');document.getElementById('years-label')&&(document.getElementById('years-label').textContent=y+' years');document.getElementById('sim-years')&&(document.getElementById('sim-years').textContent=y);document.getElementById('sim-total')&&(document.getElementById('sim-total').innerHTML=`₹${ml}<small> L</small>`);document.getElementById('sim-growth')&&(document.getElementById('sim-growth').textContent=fmt(fv-m*12*y));document.getElementById('sim-monthly')&&(document.getElementById('sim-monthly').textContent=fmt(m));};
  simKeys.forEach(k=>document.getElementById(k)?.addEventListener('input',updateSim));
  document.querySelector('[data-act="reset-sim"]')?.addEventListener('click',()=>{for(const [k,v] of Object.entries({monthly:25000,rate:10,years:10})){const el=document.getElementById(k);if(el)el.value=v}updateSim()});
  const updateWealth=()=>{const m=Number(document.getElementById('wealth-month')?.value||10000),r=Number(document.getElementById('wealth-rate')?.value||10),y=Number(document.getElementById('wealth-years')?.value||10);const mr=r/1200,n=y*12,total=mr?m*((Math.pow(1+mr,n)-1)/mr):m*n;const inv=m*12*y;const fmt=n=>(n/100000).toFixed(1)+'L';const labels={'wealth-month-label':'₹'+m.toLocaleString('en-IN'),'wealth-rate-label':r+'%','wealth-years-label':y+' yrs','wealth-years-copy':y,'wealth-total':`₹${(total/100000).toFixed(1)} <small>L</small>`,'wealth-invested':'₹'+fmt(inv),'wealth-growth':'₹'+fmt(total-inv)};for(const [id,text] of Object.entries(labels)){const el=document.getElementById(id);if(el)el.innerHTML=text}};
  ['wealth-month','wealth-rate','wealth-years'].forEach(id=>document.getElementById(id)?.addEventListener('input',updateWealth));
  document.getElementById('ctc')?.addEventListener('input',e=>{const gross=Number(e.target.value)/12,net=gross*.84,fmt=n=>'₹'+Math.round(n).toLocaleString('en-IN');document.getElementById('gross-monthly').textContent=fmt(gross);document.getElementById('net-monthly').textContent=fmt(net);document.getElementById('takehome').textContent=fmt(net);document.getElementById('deductions').textContent=fmt(gross-net)});
}
render();

if(apiToken||location.port!=='5173')refreshAccount();

function bindRobot(){const panel=document.querySelector('.assistant-panel'),stage=document.querySelector('.robot-stage');if(!panel||!stage||matchMedia('(prefers-reduced-motion: reduce)').matches)return;let frame=0;panel.addEventListener('pointermove',event=>{if(event.pointerType==='touch')return;const box=panel.getBoundingClientRect(),x=(event.clientX-box.left)/box.width,y=(event.clientY-box.top)/box.height;const dx=Math.max(-22,Math.min(22,(x-.5)*44)),dy=Math.max(-16,Math.min(16,(y-.3)*32));cancelAnimationFrame(frame);frame=requestAnimationFrame(()=>{stage.style.setProperty('--robot-x',`${dx}px`);stage.style.setProperty('--robot-y',`${dy}px`)})});panel.addEventListener('pointerleave',()=>{stage.style.setProperty('--robot-x','0px');stage.style.setProperty('--robot-y','0px')})}
